let html = $json.body || $json.data || $json.html || $json.text || "";

// 1. Hapus script, style, metadata
html = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<meta[\s\S]*?>/gi, '')
  .replace(/<head[\s\S]*?<\/head>/gi, '');

// 2. <li> jadi bullet "-"
html = html
  .replace(/<li[^>]*>/gi, '\n- ')
  .replace(/<\/li>/gi, '');

// 3. Paragraf & break jadi newline
html = html
  .replace(/<\/p>/gi, '\n')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/div>/gi, '\n');

// 4. Hapus semua tag HTML lain
html = html.replace(/<[^>]+>/g, ' ');

// 5. Hapus nomor halaman
html = html.replace(/Page \d+ of \d+/gi, '');
html = html.replace(/\bPage\s*\d+\b/gi, '');
html = html.replace(/^\s*\d+\s*$/gm, '');

// 6. Hapus footer umum, beri jarak pada judul CV
html = html.replace(/\b(Curriculum Vitae|Resume|CV)\b/gi, (m) => `\n${m}\n`);
html = html.replace(/©.*\n/gi, '');
html = html.replace(/All rights reserved.*/gi, '');

// 7. Decode HTML entities
html = html
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'");

// 8. Rapikan spasi & baris
html = html
  .replace(/\n\s*\n\s*\n+/g, '\n\n')
  .replace(/[ \t]+/g, ' ')
  .replace(/\s+\n/g, '\n')
  .replace(/\n\s+/g, '\n')
  .trim();

return [{ json: { clean_text: html } }];

// 1. Ambil teks mentah dari Gemini
const rawText = $json.text || $json.output || "";

// 2. Temukan blok JSON (abaikan pembungkus ```json)
const jsonMatch = rawText.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  throw new Error("Tidak dapat menemukan JSON dalam output AI.");
}

// 3. Parse menjadi objek
try {
  return [{ json: JSON.parse(jsonMatch[0]) }];
} catch (error) {
  throw new Error("Gagal mem-parsing JSON: " + error.message);
}

const data = $json;
const MIN_SCORE = 6; // <-- ubah batas minimum skor di sini

const safeArray = (x) => Array.isArray(x) && x.length > 0 ? x.join(", ") : "-";
const esc = (s) => String(s ?? "-").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const cat = data.category || {};
const itScore = Number(data.it_difficulty_score) || 0;
const teachScore = Number(data.teaching_score) || 0;
const lolos = itScore >= MIN_SCORE && teachScore >= MIN_SCORE;

let fileName = "-";
try { fileName = $('Google Drive Trigger').first().json.name || "-"; } catch (e) {}
const nama = data.candidate_name && data.candidate_name !== "" ? data.candidate_name : fileName;

const msg = `👤 <b>Kandidat:</b> ${esc(nama)}
📄 <b>File:</b> ${esc(fileName)}

📌 <b>Keyword IT</b>
${esc(safeArray(data.it_keywords))}

🎓 <b>Keyword Mengajar</b>
${esc(safeArray(data.teaching_keywords))}

📂 <b>Kategori</b>
DevOps: ${esc(safeArray(cat.devops))}
Backend: ${esc(safeArray(cat.backend))}
Frontend: ${esc(safeArray(cat.frontend))}
Security: ${esc(safeArray(cat.cybersecurity || cat.security))}
Cloud: ${esc(safeArray(cat.cloud))}
Networking: ${esc(safeArray(cat.networking))}

⭐ <b>Skor Teknis IT:</b> ${itScore || "-"} / 10
⭐ <b>Skor Mengajar:</b> ${teachScore || "-"} / 10
${lolos ? "✅" : "❌"} <b>Status (min. ${MIN_SCORE}):</b> ${lolos ? "LOLOS seleksi awal" : "Di bawah batas minimum"}

📝 <b>Ringkasan:</b>
${esc(data.summary)}`;

return [{ json: { telegram_text: msg } }];
